<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\DeliveryZone; use Illuminate\Http\Request;
class DeliveryZoneController extends Controller { public function index(){return view('admin.delivery-zones',['zones'=>DeliveryZone::orderBy('district')->get()]);} public function store(Request $r){$d=$r->validate(['district'=>'required|string|max:120|unique:delivery_zones,district','charge'=>'required|numeric|min:0']);$d['is_active']=$r->boolean('is_active');DeliveryZone::create($d);return back()->with('success','District delivery charge added.');} public function update(Request $r,DeliveryZone $deliveryZone){$d=$r->validate(['district'=>'required|string|max:120|unique:delivery_zones,district,'.$deliveryZone->id,'charge'=>'required|numeric|min:0']);$d['is_active']=$r->boolean('is_active');$deliveryZone->update($d);return back()->with('success','Delivery charge updated.');} public function destroy(DeliveryZone $deliveryZone){$deliveryZone->delete();return back()->with('success','Delivery zone deleted.');} }
